<?php $toolBuilds=$meta['evidence']['tool_builds']??[];$toolReviews=$meta['evidence']['tool_reviews']??[];if($toolBuilds||$toolReviews): ?>
<section id="tool-builds"><h2>Research tool files &amp; tests</h2><p class="fine">Source and tests are inert text under <?=e(RT_LICENSE)?>. Execution is contributor-reported. Inspect code before running in your own tools. Passing tests does not establish scientific validity.</p>
<?php foreach($toolBuilds as $build): ?><article class="task-brief"><h3><?=e($build['title'])?></h3><p><strong><?=e($build['status'])?></strong> · Version <?=e($build['version'])?> · <?=e($build['license'])?></p>
<?php if($admission==='accepted'): try{rt_read($r['id'],$result['id']);$toolDownload=true;}catch(HttpError){$toolDownload=false;}if($toolDownload): ?><a class="button secondary" href="<?=e($base)?>/results/<?=e($result['id'])?>/tools/<?=e($build['id'])?>/bundle.json">Download tool bundle</a><?php else: ?><p class="notice">Historical build; download the current accepted version from the workflow.</p><?php endif;else: ?><p class="notice">Submitted files are not accepted evidence and cannot be downloaded as a tool bundle.</p><?php endif ?>
<?php foreach(['usage'=>'Usage','environment'=>'Environment and versions','command'=>'Run command','dependency_notes'=>'Dependencies and third-party rights','scientific_assumptions'=>'Scientific assumptions','limitations'=>'Limitations','maintenance'=>'Maintenance or experimental status'] as $key=>$label): ?><details><summary><?=e($label)?></summary><?=prose($build[$key])?></details><?php endforeach ?>
<details><summary>Recorded software versions</summary><?php if(!isset($build['software'])): ?><p>Historical record: software versions were not collected separately.</p><?php else: foreach($build['software'] as $software): ?><p><?=e($software['name'])?> · <?=e($software['version']?:'Not recorded')?></p><?php endforeach;endif ?></details>
<h4>Reproducible test cases</h4><?php foreach($build['tests'] as $test): ?><details><summary><?=e($test['id'])?> · <?=e($test['kind'])?> · <?=e($test['status'])?></summary><p><?=e($test['purpose'])?></p><dl class="metadata"><?php foreach(['input','expected','observed','comparison','absolute_tolerance','relative_tolerance','tolerance_reason','run_log'] as $key): ?><dt><?=e(ucwords(str_replace('_',' ',$key)))?></dt><dd><?=e($test[$key])?></dd><?php endforeach ?></dl></details><?php endforeach ?>
<details><summary>Exact source &amp; test files (<?=count($build['files'])?>)</summary><?php foreach($build['files'] as $file): ?><h4><?=e($file['name'])?> · <?=e($file['role'])?></h4><?php if(!empty($toolDownload)&&$admission==='accepted'): ?><a href="<?=e($base)?>/results/<?=e($result['id'])?>/tools/<?=e($build['id'])?>/files/<?=e($file['id'])?>">Save <?=e($file['name'])?></a><?php endif ?><p class="fine">SHA-256 <?=e($file['sha256'])?></p><pre><?=e($file['content'])?></pre><?php endforeach ?></details></article><?php endforeach ?>
<?php foreach($toolReviews as $review): ?><article class="task-brief"><h3>Independent tool review · <?=e($review['verdict'])?></h3><p><a href="<?=e($base)?>/results/<?=e($review['result_id'])?>">Reviewed build <?=e($review['tool_id'])?></a></p><?php foreach(['method','environment','command','run_log','scientific_assessment','limitations'] as $key): ?><h4><?=e(ucwords(str_replace('_',' ',$key)))?></h4><?=prose($review[$key])?><?php endforeach ?><details><summary>Independently rerun test cases</summary><?php foreach($review['test_results'] as $test): ?><h4><?=e($test['id'])?> · <?=e($test['status'])?></h4><p>Observed: <?=e($test['observed'])?></p><?=prose($test['run_log'])?><?php endforeach ?></details></article><?php endforeach ?>
</section><?php endif ?>